public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];
    int depositCount = 0;

    for (int i = 0; i < numRows; i++) {
        for (int j = 0; j < numCols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                dfs(grid, visited, i, j);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == '*' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    // Explore all 8 possible directions
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int d = 0; d < 8; d++) {
        dfs(grid, visited, row + rowDirections[d], col + colDirections[d]);
    }
}

