public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int currentX, int currentY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (currentX == endX && currentY == endY) {
        return true;
    }

    if (currentX < 0 || currentX >= n || currentY < 0 || currentY >= n || visited[currentX][currentY]) {
        return false;
    }

    visited[currentX][currentY] = true;

    for (int[] path : paths) {
        int nextX = currentX + path[0];
        int nextY = currentY + path[1];

        if (canTravel(n, nextX, nextY, endX, endY, paths, visited)) {
            return true;
        }
    }

    visited[currentX][currentY] = false;
    return false;
}

public static String appx(String word1, String word2) {
