    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int commonCount = 0;
    for (int i = 0; i < 26; i++) {
        commonCount += Math.min(count1[i], count2[i]);
    }

    int sumOfLengths = word1.length() + word2.length();

    if (sumOfLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(commonCount, sumOfLengths);
    String fraction = (commonCount / gcd) + "/" + (sumOfLengths / gcd);

    return "appx(" + word1 + ", " + word2 + ") = " + fraction;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

