public int minInsertions(String s) {
    int openCount = 0; // To track the number of unmatched '('
    int insertions = 0; // To track the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            openCount++;
        } else {
            // If it's a closing bracket ')'
            if (openCount > 0) {
                // If there's a matching '(', decrement the openCount
                openCount--;
            } else {
                // If there's no matching '(', increment the insertions count
                insertions++;
            }
            // Check the next character to see if it's also a closing bracket
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                // If it is, skip the next character as it forms a "))"
                i++;
            } else {
                // If it's not, we need to insert a ')' to form a valid "())"
                insertions++;
            }
        }
    }

    // Add the remaining unmatched '('
    insertions += openCount;

    return insertions;
}

