public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    for (int i = 0; i <= 9; i++) {
        if (i >= low) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, i, high, result);
    }

    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int current, int lastDigit, int high, List<Integer> result) {
    if (current > high) {
        return;
    }

    int last = lastDigit % 10;
    int next[] = new int[] {last - 1, last + 1};

    for (int step : next) {
        if (step >= 0 && step <= 9) {
            int nextNumber = current * 10 + step;
            if (nextNumber <= high) {
                result.add(nextNumber);
                findSteppingNumbersHelper(nextNumber, step, high, result);
            }
        }
    }
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    int count = 0;
    long factor = 1;
    int lowerNum = 0, currentDigit = 0, higherNum = 0;

    while (n / factor != 0) {
        lowerNum = (int) (n - (n / factor) * factor);
        currentDigit = (int) ((n / factor) % 10);
        higherNum = (int) (n / (factor * 10));

        if (currentDigit == 0) {
            count += higherNum * factor;
        } else if (currentDigit == 1) {
            count += higherNum * factor + lowerNum + 1;
        } else {
            count += (higherNum + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

