}

private static void backtrack(int[] A, boolean[] used, List<Integer> current, int[] count) {
    if (current.size() == A.length) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i]) continue;
        if (current.size() == 0 || isPerfectSquare(current.get(current.size() - 1) + A[i])) {
            used[i] = true;
            current.add(A[i]);
            backtrack(A, used, current, count);
            current.remove(current.size() - 1);
            used[i] = false;

            // Skip duplicates
            while (i < A.length - 1 && A[i] == A[i + 1]) {
                i++;
            }
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;

    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[stack[top]] >= heights[i]) {
            int height = heights[stack[top--]];
            int width = top != -1 ? i - stack[top] - 1 : i;
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top--]];
        int width = top != -1 ? n - stack[top] - 1 : n;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int row = 0, col = 0, d = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];
        if ((row + col) % 2 == 0) { // moving up
            if (col == cols - 1) {
                row++;
            } else if (row == 0) {
                col++;
            } else {
                row--;
                col++;
            }
        } else { // moving down
            if (row == rows - 1) {
                col++;
            } else if (col == 0) {
                row++;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the first digit that is smaller than the digit next to it
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the sequence after i
    i++;
    j = digits.length - 1;
    while (i < j) {
        temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;
        i++;
        j--;
    }

    // Convert the character array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case of integer overflow
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    return generateCenterSymmetricNumbers(n, n);
}

private static List<String> generateCenterSymmetricNumbers(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return new ArrayList<>(List.of(""));
    }
    if (currentLength == 1) {
        return new ArrayList<>(List.of("0", "1", "8"));
    }

    List<String> prevResults = generateCenterSymmetricNumbers(currentLength - 2, targetLength);
    List<String> results = new ArrayList<>();

    for (String s : prevResults) {
        if (currentLength != targetLength) {
            results.add("0" + s + "0");
        }
        results.add("1" + s + "1");
        results.add("6" + s + "9");
        results.add("8" + s + "8");
        results.add("9" + s + "6");
    }

    return results;
}

public static boolean isBoomerang(int[][] points) {
    // A boomerang must have three distinct points
    if (points.length != 3) {
        return false;
    }

    // Extract points
    int[] point1 = points[0];
    int[] point2 = points[1];
    int[] point3 = points[2];

    // Check for distinct points
    if ((point1[0] == point2[0] && point1[1] == point2[1]) ||
        (point2[0] == point3[0] && point2[1] == point3[1]) ||
        (point1[0] == point3[0] && point1[1] == point3[1])) {
        return false;
    }

    // Calculate the area of the triangle formed by the points
    // Area = 0.5 * | x1(y2-y3) + x2(y3-y1) + x3(y1-y2) |
    // If the area is 0, the points are collinear and do not form a boomerang
    int area = point1[0] * (point2[1] - point3[1]) +
               point2[0] * (point3[1] - point1[1]) +
               point3[0] * (point1[1] - point2[1]);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The input must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int factor2 = 2, factor3 = 3, factor5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(factor2, Math.min(factor3, factor5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == factor2) {
            index2++;
            factor2 = 2 * uglyNumbers[index2];
        }

        if (nextUglyNumber == factor3) {
            index3++;
            factor3 = 3 * uglyNumbers[index3];
        }

        if (nextUglyNumber == factor5) {
            index5++;
            factor5 = 5 * uglyNumbers[index5];
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
            maxEnergy = Math.max(maxEnergy, currentEnergy);
        } else {
            currentEnergy = 1;
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    Map<Integer, Integer> frequencyMap = new HashMap<>();

    // Count the frequency of each number
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    int uniqueSum = 0;

    // Sum up numbers that appear only once
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }

    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: i = 1 + 1 + ... + 1 (i times)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String reversedWord = new StringBuilder(words[i]).reverse().toString();
        result.append(reversedWord);
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}
